document.addEventListener('click',e=>{const b=e.target.closest('[data-subir-parada]');if(!b||!planVista)return;const orden=planVista.resultado.orden.slice(),i=orden.indexOf(b.dataset.subirParada);if(i<=0)return;[orden[i-1],orden[i]]=[orden[i],orden[i-1]];const r=LogisticaRutas.validarOrden({...planVista,orden});if(!r.viable){avisar(r.razones.join('; '));return;}planVista.resultado=r;mostrarPlan();baseLocal.guardarMeta('borradorRuta',planVista).catch(e=>avisar(e.message));});

async function estoyAqui(){const ns=await puntosNegocios();$('app').innerHTML='<h1>Estoy aquí</h1><p>Busca negocios con ubicación confirmada a tu alrededor. La ubicación actual no sustituye el pin de ningún establecimiento.</p><form id="form-aqui" class="panel">'+campo('radio','Radio de búsqueda en metros','number','3000','min="100" max="50000" required')+campo('zona','Zona (opcional)')+'<button>Buscar desde mi ubicación</button></form><div id="candidatos-aqui"></div>';$('form-aqui').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!navigator.geolocation){avisar('GPS no disponible');return;}navigator.geolocation.getCurrentPosition(p=>{const origen={lat:p.coords.latitude,lon:p.coords.longitude};const candidatos=LogisticaRutas.seleccionarCandidatos(ns,{hoy:fechaHoy(),zona:f.get('zona')||undefined}).map(n=>({...n,metros:LogisticaRutas.distancia(origen,n)})).filter(n=>n.metros<=Number(f.get('radio'))).sort((a,b)=>b.prioridad-a.prioridad||a.metros-b.metros).slice(0,10);$('candidatos-aqui').innerHTML=candidatos.map(n=>`<article class="panel"><h2>${esc(n.nombre)}</h2><p>${Math.round(n.metros)} m en línea recta · ${esc(n.razones.join(', '))}</p>${botonExtra('agregar-ruta','Agregar a salida',n.id)}<button data-negocio="${n.id}">Expediente</button></article>`).join('')||'<p>No hay candidatos confirmados dentro de ese radio. Amplía el radio o completa ubicaciones.</p>';},()=>avisar('No se pudo obtener tu ubicación. Prepara una zona desde la pantalla Preparar salida.'),{enableHighAccuracy:true,timeout:12000});};}

document.addEventListener('click',async e=>{if(e.target.id!=='trafico'||!apiComercial||!planVista?.resultado.viable)return;const puntos=[planVista.inicio,...planVista.resultado.orden.map(id=>planVista.paradas.find(p=>p.id===id)),planVista.fin],pares=puntos.slice(1).map((p,i)=>({origenId:puntos[i].id,destinoId:p.id}));async function consultar(confirmarExcedente=false){const d=await apiComercial.post({tipo:'comercial_ruta',modo:'TRAFICO_HOY',pares,fechaSalida:new Date(Date.now()+60000).toISOString(),confirmarExcedente,puntosTransitorios:[planVista.inicio,planVista.fin].map(p=>({id:p.id,lat:p.lat,lng:p.lon,confirmada:true,confirmadoTs:planVista.confirmadoTs}))});await logisticaGuardarCuota(d.cuota);$('trafico-hoy').innerHTML='<h3>Tráfico para esta consulta</h3>'+d.tramos.map(t=>`<p>${esc(puntos.find(p=>p.id===t.origenId)?.nombre||'Inicio')} → ${esc(puntos.find(p=>p.id===t.destinoId)?.nombre||'Destino final')}: ${Math.ceil(t.duracionSeg/60)} min</p>`).join('')+`<p>Uso: ${d.cuota.usadosMes} / ${d.cuota.franquiciaMes} elementos · gasto estimado USD ${d.cuota.estimacionUSD}. No se guardó esta respuesta.</p>`;}try{await consultar();}catch(error){if(error.respuesta?.codigo==='CONFIRMAR_EXCEDENTE')abrirDetalle('Confirmar cálculo fuera de franquicia',`<p>${error.respuesta.elementosCobrables} elementos adicionales; ${error.respuesta.usadosMes} usados este mes.</p><label><input type="checkbox" required> Autorizo este cálculo con posible cargo del proveedor</label>`,()=>consultar(true));else avisar(error.message);}});
